import { describe, expect, it } from 'vitest';
import { isComplete, parseXml } from './xml.js';
import { EngineError } from '../core/check.js';

describe('isComplete', () => {
  it('accepts a closed root after a prolog, doctype and comments', () => {
    const doc = [
      '<?xml version="1.0" ?>',
      '<!DOCTYPE coverage SYSTEM "http://cobertura.sourceforge.net/xml/coverage-04.dtd">',
      '<!-- Generated by coverage.py -->',
      '<coverage><packages/></coverage>',
      '',
    ].join('\n');
    expect(isComplete(doc)).toBe(true);
    expect(isComplete('<testsuites name="x"/>\n')).toBe(true);
  });

  it('rejects a report cut short, text that is not XML, and nothing at all', () => {
    expect(isComplete('<testsuites><testsuite name="a"><testcase name="x"/>')).toBe(false);
    expect(isComplete('<coverage><line num="1"/>')).toBe(false);
    expect(isComplete('no xml here')).toBe(false);
    expect(isComplete('')).toBe(false);
  });
});

describe('parseXml', () => {
  it('reads attributes and text, with the named elements as lists', () => {
    expect(parseXml('<a x="1"><b>t &amp; u</b></a>', 'test', ['b'])).toEqual({
      a: { '@_x': '1', b: ['t & u'] },
    });
  });

  it('throws an engine error for a truncated or malformed document', () => {
    expect(() => parseXml('<a><b>', 'JUnit', [])).toThrow(
      new EngineError('the JUnit report is not a complete XML document'),
    );
    expect(() => parseXml('<a b="1></a>', 'Clover', [])).toThrow(
      new EngineError('the Clover report is not well-formed XML'),
    );
  });
});
